import { code } from '../../code.ts';
import { pascal } from '../names.ts';
import type { Plugin } from '../values.ts';

// The path of the file in plugins/android.
export const path = ({ id }: Plugin) => `${id}/src/main/cpp/CMakeLists.txt`;

export default ({ id, sources, includeDirectories }: Plugin) => code`
# Generated by plugins/tools/generate.ts from plugins/plugins/${id}/plugin.json; do not edit.
cmake_minimum_required(VERSION 3.24)
project(MapLibre${pascal(id)} LANGUAGES CXX)

# Consume only the C header from the SDK AAR, never another copy of mbgl-core.
find_package(MapLibreAndroid REQUIRED CONFIG)
get_filename_component(PLUGIN_ROOT "\${CMAKE_CURRENT_SOURCE_DIR}/../../../../../plugins/${id}" ABSOLUTE)

add_library(${id}-core STATIC
${sources.map((name) => `    "\${PLUGIN_ROOT}/shared/cpp/${name}"`).join('\n')}
)
target_compile_features(${id}-core PUBLIC cxx_std_20)
set_target_properties(${id}-core PROPERTIES POSITION_INDEPENDENT_CODE ON)
target_include_directories(${id}-core PUBLIC
${includeDirectories.map((name) => `    "\${PLUGIN_ROOT}/${name}"`).join('\n')}
)
target_link_libraries(${id}-core PUBLIC MapLibreAndroid::maplibre)

add_library(${id} SHARED plugin.cpp)
target_link_libraries(${id} PRIVATE ${id}-core dl)
`;
